/**
 * Test script for KnockoutJS Template Binding Error Debugger
 */

const { createDebugHelper } = require('./ko-debug.js');

// Define a sample ViewModel
const viewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create the debug helper
const debugHelper = createDebugHelper(viewModel);

let allPassed = true;

/**
 * Run a single test
 */
function runTest(testName, actualResult, expectedProperty, expectedValue) {
  const actualValue = actualResult[expectedProperty];
  const passed = JSON.stringify(actualValue) === JSON.stringify(expectedValue);

  if (passed) {
    console.log(`PASS: ${testName}`);
  } else {
    console.log(`FAIL: ${testName}`);
    console.log(`  Expected ${expectedProperty} to be: ${JSON.stringify(expectedValue)}`);
    console.log(`  Actual ${expectedProperty} was: ${JSON.stringify(actualValue)}`);
    allPassed = false;
  }
}

// Test 1: Diagnose missing property "item" (should suggest "items")
console.log('\nTest 1: Diagnose missing property "item"');
const result1 = debugHelper.diagnoseMissingProperty('item');
runTest('Missing property "item" has correct structure', result1, 'error', true);
runTest('Missing property "item" correctly identifies missing property', result1, 'missingProperty', 'item');
runTest('Missing property "item" suggests "items"', result1, 'suggestion', 'items');
runTest('Missing property "item" includes all available properties', result1, 'availableProperties', 
  ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount']);

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
console.log('\nTest 2: Diagnose missing property "selctedItem"');
const result2 = debugHelper.diagnoseMissingProperty('selctedItem');
runTest('Missing property "selctedItem" correctly identifies missing property', result2, 'missingProperty', 'selctedItem');
runTest('Missing property "selctedItem" suggests "selectedItem"', result2, 'suggestion', 'selectedItem');

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
console.log('\nTest 3: Diagnose missing property "completelyWrong"');
const result3 = debugHelper.diagnoseMissingProperty('completelyWrong');
runTest('Missing property "completelyWrong" correctly identifies missing property', result3, 'missingProperty', 'completelyWrong');
runTest('Missing property "completelyWrong" has null suggestion', result3, 'suggestion', null);

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
console.log('\nTest 4: Diagnose missing property "isLoad"');
const result4 = debugHelper.diagnoseMissingProperty('isLoad');
runTest('Missing property "isLoad" correctly identifies missing property', result4, 'missingProperty', 'isLoad');
runTest('Missing property "isLoad" suggests "isLoading"', result4, 'suggestion', 'isLoading');

// Final summary
console.log('\n-------------------');
if (allPassed) {
  console.log('All tests passed!');
  process.exit(0);
} else {
  console.log('Some tests failed!');
  process.exit(1);
}
ENDOFFILE"}

